def solve_game(N):
    """
    Calculates the guaranteed number of uncovered squares U(N) for a row of N squares
    using minimax search with memoization.
    """
    memo = {}

    def state_to_int(state):
        # Convert tuple of 0/1 (0=Uncovered, 1=Covered) to an integer for memoization key
        return int("".join(map(str, state)), 2)

    def find_moves(state):
        moves = []
        state_list = list(state)
        for i in range(N - 1):
            if state_list[i] == 0 and state_list[i+1] == 0:
                # Move involves placing a tile covering (i, i+1)
                new_state_list = list(state_list)
                new_state_list[i] = 1
                new_state_list[i+1] = 1
                moves.append(tuple(new_state_list))
        return moves

    # V(state, is_alice_turn): Returns the guaranteed final uncovered count
    def minimax(state, is_alice_turn):
        state_key = (state, is_alice_turn)
        if state_key in memo:
            return memo[state_key]

        possible_moves = find_moves(state)

        # Terminal state check
        if not possible_moves:
            uncovered_count = sum(1 for x in state if x == 0)
            return uncovered_count

        if is_alice_turn:
            # Alice maximizes the final uncovered count
            max_value = -1
            for next_state in possible_moves:
                # Recurse: next turn is Bob's
                value = minimax(next_state, False)
                max_value = max(max_value, value)
            result = max_value
        else:
            # Bob minimizes the final uncovered count
            min_value = N + 1
            for next_state in possible_moves:
                # Recurse: next turn is Alice's
                value = minimax(next_state, True)
                min_value = min(min_value, value)
            result = min_value

        memo[state_key] = result
        return result

    # Initial state: all 0s (uncovered)
    initial_state = tuple([0] * N)
    # Alice starts (True)
    return minimax(initial_state, True)

# Calculate U(N) for N=1 to N=10
